rows.statement:
if actual_definition is distinct from
 $source_expected_predecessor$CHECK (resolution_kind IS NULL OR (resolution_kind = ANY (ARRAY['SOURCE_MATCHED'::text, 'OFFICE_ACCEPTED_SYSTEM_HOURS'::text, 'CANDIDATE_CORRECTED'::text, 'MANAGER_CONFIRMED_SYSTEM_HOURS'::text, 'RECORDED_NOT_WORKED'::text, 'CORRECT_FINAL_SOURCE'::text])))$source_expected_predecessor$ then
  raise exception 'SOURCE_INCIDENT_RESOLUTION_PREDECESSOR_MISMATCH' using errcode='55000';

select * into strict v_fin from public.timesheets_financials financial
      where financial.id=(v_write->>'timesheet_financials_id')::uuid
        and financial.timesheet_id=v_root.timesheet_id and financial.is_current;

select * into v_local from private.weekly_source_local_protected_decision_receipts local_receipt
    where local_receipt.state='PENDING_FREEZE'
      and local_receipt.result_json->>'decision_bundle_id'=new.decision_bundle_id::text for update;

select * into strict v_publication from public.weekly_source_projection_publications p
      where p.upload_id=v_upload.id and p.source_cycle_id=v_upload.source_cycle_id
        and p.report_scope_id is not distinct from v_upload.report_scope_id and p.state='CURRENT';
